import { useRef, useState } from 'react'
import { getPointsRecordList, OrderManagementTypes } from '@/apis/admin/order-management'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProFormInstance, ProColumns } from '@ant-design/pro-components'
import { message, Tag, DatePicker } from 'antd'
import {
  ArrowUpOutlined,
  ArrowDownOutlined,
  MinusCircleOutlined,
  RollbackOutlined
} from '@ant-design/icons'
import dayjs from 'dayjs'

// 流水类型映射
const pointsTypeMap: Record<number, { text: string; color: string; icon: React.ReactNode }> = {
  1: { text: '发放', color: 'success', icon: <ArrowUpOutlined /> },
  2: { text: '消耗', color: 'processing', icon: <ArrowDownOutlined /> },
  3: { text: '过期', color: 'error', icon: <MinusCircleOutlined /> },
  4: { text: '退回', color: 'warning', icon: <RollbackOutlined /> }
}

// 来源映射
const sourceMap: Record<number, string> = {
  1: '注册赠送',
  2: '手工赠送',
  3: '订单抵扣',
  4: '订单取消',
  5: '自动过期'
}

// 格式化时间
const formatTime = (time: string) => {
  if (!time) {
    return '-'
  }
  return dayjs(time).format('YYYY-MM-DD HH:mm:ss')
}

// 格式化过期时间
const formatExpireTime = (timestamp: number) => {
  if (!timestamp) {
    return '-'
  }
  return dayjs(timestamp * 1000).format('YYYY-MM-DD HH:mm:ss')
}

const PointsLedger: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const formRef = useRef<ProFormInstance>()
  const [dateRange, setDateRange] = useState<[dayjs.Dayjs | null, dayjs.Dayjs | null]>([null, null])

  // 表格列定义
  const columns: ProColumns<OrderManagementTypes.PointsRecordListDto>[] = [
    {
      title: '流水号',
      dataIndex: 'serialNo',
      key: 'serialNo',
      width: 180,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '用户',
      key: 'user',
      width: 160,
      hideInSearch: true,
      render: (_, record) => (
        <div>
          <div style={{ fontWeight: 500 }}>{record.username}</div>
          <div style={{ fontSize: 12, color: '#64748B' }}>ID: {record.userId}</div>
        </div>
      )
    },
    {
      title: '用户昵称',
      dataIndex: 'username',
      key: 'username',
      width: 140,
      hideInTable: true,
      search: {
        transform: value => ({ username: value })
      }
    },
    {
      title: '类型',
      dataIndex: 'type',
      key: 'type',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '发放' },
        2: { text: '消耗' },
        3: { text: '过期' },
        4: { text: '退回' }
      },
      render: (_, record) => {
        const type = pointsTypeMap[record.type]
        return (
          <Tag color={type?.color || 'default'} icon={type?.icon}>
            {type?.text || '未知'}
          </Tag>
        )
      }
    },
    {
      title: '来源',
      dataIndex: 'source',
      key: 'source',
      width: 120,
      valueType: 'select',
      valueEnum: {
        1: { text: '注册赠送' },
        2: { text: '手工赠送' },
        3: { text: '订单抵扣' },
        4: { text: '订单取消' },
        5: { text: '自动过期' }
      },
      render: (_, record) => sourceMap[record.source] || '未知'
    },
    {
      title: '积分变动',
      dataIndex: 'changePoints',
      key: 'changePoints',
      width: 120,
      hideInSearch: true,
      render: text => {
        const points = Number(text)
        const isPositive = points > 0
        return (
          <span
            style={{
              fontFamily: 'Courier New, monospace',
              fontWeight: 600,
              color: isPositive ? '#10B981' : '#EF4444'
            }}
          >
            {isPositive ? `+${points}` : points}
          </span>
        )
      }
    },
    {
      title: '变动后余额',
      dataIndex: 'afterPoints',
      key: 'afterPoints',
      width: 120,
      hideInSearch: true,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>
          {Number(text).toLocaleString()}
        </span>
      )
    },
    {
      title: '关联单据',
      dataIndex: 'relationOrderId',
      key: 'relationOrderId',
      width: 160,
      hideInSearch: true,
      render: text => {
        if (!text) {
          return '-'
        }
        return <span style={{ fontFamily: 'Courier New, monospace', fontSize: 13 }}>{text}</span>
      }
    },
    {
      title: '过期时间',
      dataIndex: 'expireTime',
      key: 'expireTime',
      width: 170,
      hideInSearch: true,
      render: text => (
        <span style={{ fontSize: 13, color: '#666' }}>{formatExpireTime(text as number)}</span>
      )
    },
    {
      title: '时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 170,
      hideInSearch: true,
      render: text => (
        <span style={{ fontSize: 13, whiteSpace: 'nowrap' }}>{formatTime(text as string)}</span>
      )
    },
    {
      title: '时间范围',
      key: 'dateRange',
      hideInTable: true,
      renderFormItem: () => (
        <DatePicker.RangePicker
          style={{ width: '100%' }}
          value={dateRange}
          onChange={dates => setDateRange(dates as [dayjs.Dayjs | null, dayjs.Dayjs | null])}
        />
      ),
      search: {
        transform: value => {
          if (dateRange && dateRange[0] && dateRange[1]) {
            return {
              createdAtStart: dateRange[0].format('YYYY-MM-DD'),
              createdAtEnd: dateRange[1].format('YYYY-MM-DD')
            }
          }
          return {}
        }
      }
    }
  ]

  return (
    <ExcelTable
      key="points-ledger-list"
      formRef={formRef}
      columns={columns}
      requestFn={async params => {
        const { page, pageSize, username, type, source, createdAtStart, createdAtEnd, ...rest } =
          params
        return await getPointsRecordList({
          page,
          pageSize,
          username,
          type,
          source,
          createdAtStart,
          createdAtEnd,
          ...rest
        })
      }}
      actionRef={actionRef}
      rowSelection={false}
      options={{
        fullScreen: false,
        reload: true,
        setting: false,
        density: false
      }}
      toolBarRenderFn={() => []}
      scroll={{ x: 1300 }}
    />
  )
}

export default PointsLedger
